function maxSlidingWindow(nums, k) {
    const output = [];
    const q = []; // store indices
    let l = 0, r = 0;
    while (r < nums.length) {
        while (q.length > 0 && nums[q[q.length - 1]] < nums[r]) {
            q.pop();
        }
        q.push(r);
        if (l > q[0]) {
            q.shift();
        }
        if (r + 1 >= k) {
            output.push(nums[q[0]]);
            l++;
        }
        r++;
    }
    return output;
}
